import re

def parse_version(v):
    pattern = r'^(?P<major>0|[1-9]\d*)\.(?P<minor>0|[1-9]\d*)\.(?P<patch>0|[1-9]\d*)(?:-(?P<pre>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+(?P<build>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
    m = re.fullmatch(pattern, v)
    if not m:
        raise ValueError(f'Invalid version: {v}')
    major = int(m.group('major'))
    minor = int(m.group('minor'))
    patch = int(m.group('patch'))
    pre = m.group('pre')
    # validate pre-release identifiers
    pre_ids = []
    if pre is not None:
        for ident in pre.split('.'):
            if not ident:
                raise ValueError(f'Empty pre-release identifier in {v}')
            if ident.isdigit():
                # must not have leading zero unless it's exactly "0"
                if len(ident) > 1 and ident[0] == '0':
                    raise ValueError(f'Leading zero in numeric pre-release identifier {ident} in {v}')
            pre_ids.append(ident)
    # build metadata ignored but could validate similarly if needed (not required)
    return (major, minor, patch, pre_ids)

def compare_prerelease(a_ids, b_ids):
    for i in range(min(len(a_ids), len(b_ids))):
        a = a_ids[i]
        b = b_ids[i]
        a_is_num = a.isdigit()
        b_is_num = b.isdigit()
        if a_is_num and b_is_num:
            ai = int(a)
            bi = int(b)
            if ai < bi: return -1
            if ai > bi: return 1
        elif a_is_num and not b_is_num:
            return -1
        elif not a_is_num and b_is_num:
            return 1
        else:
            if a < b: return -1
            if a > b: return 1
    if len(a_ids) < len(b_ids):
        return -1
    elif len(a_ids) > len(b_ids):
        return 1
    else:
        return 0

def semver_compare(a, b):
    ma, mi, pa, pre_a = parse_version(a)
    mb, mi_b, pb, pre_b = parse_version(b)
    if ma < mb: return -1
    if ma > mb: return 1
    if mi < mi_b: return -1
    if mi > mi_b: return 1
    if pa < pb: return -1
    if pa > pb: return 1
    if not pre_a and not pre_b:
        return 0
    if pre_a and not pre_b:
        return -1
    if not pre_a and pre_b:
        return 1
    return compare_prerelease(pre_a, pre_b)

def test():
    cases = [
        (("1.0.0", "2.0.0"), -1),
        (("2.1.1", "2.1.0"), 1),
        (("1.0.0-alpha", "1.0.0"), -1),
        (("1.0.0-alpha.1", "1.0.0-alpha.beta"), -1),
        (("1.0.0+build.5", "1.0.0"), 0),
    ]
    for (a,b), expected in cases:
        res = semver_compare(a,b)
        if res != expected:
            print(f'FAIL: {a} vs {b} got {res} expected {expected}')
            return
    invalid_pairs = [("1.0", "1.0.0"), ("01.0.0", "1.0.0")]
    for a,b in invalid_pairs:
        try:
            semver_compare(a,b)
            print(f'FAIL: expected ValueError for {a} vs {b}')
            return
        except ValueError:
            pass
    # pre-release leading zero invalid
    try:
        semver_compare("1.0.0-01", "1.0.0")
        print('FAIL: expected ValueError for leading zero in pre-release')
        return
    except ValueError:
        pass
    # valid zero
    try:
        semver_compare("1.0.0-0", "1.0.0")
        # should be -1 (pre-release lower)
    except ValueError:
        print('FAIL: valid zero pre-release rejected')
        return
    extra = [
        (("1.0.0-alpha", "1.0.0-alpha"), 0),
        (("1.0.0-alpha.1", "1.0.0-alpha"), 1),
        (("1.0.0-alpha.1", "1.0.0-alpha.0"), 1),
        (("1.0.0-alpha.beta", "1.0.0-alpha.1"), 1),
        (("1.0.0-alpha.2", "1.0.0-alpha.11"), -1),
        (("1.0.0-alpha-1", "1.0.0-alpha.a"), 1),  # numeric lower? Wait numeric lower means -1? Actually numeric identifier lower than any other, so "alpha-1" (numeric) < "alpha.a" => -1. Let's compute: first differing identifier: "1" vs "a". "1" is numeric, "a" is not, numeric lower => -1. So expected -1. We'll adjust.
        (("1.0.0-alpha.a", "1.0.0-alpha.-"), 1),  # 'a' vs '-', ascii: 'a'(97) > '-'(45) so a > -, thus 1
        (("1.0.0-alpha.-", "1.0.0-alpha.a"), -1),
        (("1.0.0-alpha", "1.0.0-alpha.1"), -1),
        (("1.0.0-alpha.1", "1.0.0-alpha.1"), 0),
        (("1.0.0-alpha.1", "1.0.0-alpha.2"), -1),
        (("1.0.0-alpha.2", "1.0.0-alpha.1"), 1),
    ]
    # fix the mistaken expectation
    extra_corrected = []
    for (a,b), exp in extra:
        if a == "1.0.0-alpha-1" and b == "1.0.0-alpha.a":
            exp = -1
        extra_corrected.append(((a,b), exp))
    for (a,b), exp in extra_corrected:
        res = semver_compare(a,b)
        if res != exp:
            print(f'FAIL extra: {a} vs {b} got {res} expected {exp}')
            return
    print("ALL TESTS PASSED")

if __name__ == "__main__":
    test()

